-- Back office work, Autopilot (docs/plan.md §1.123): how far Reggie goes with each play (off, draft,
-- send) and the log of what each play did. Operator-only tables. New tables only, so the previous
-- Worker keeps working. Generated by drizzle-kit; the grants and row-level security at the end are
-- hand-written.
CREATE TABLE "play_log" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"client_id" uuid,
	"flow" text NOT NULL,
	"stage" text NOT NULL,
	"play" text NOT NULL,
	"level" text NOT NULL,
	"outcome" text NOT NULL,
	"edited" boolean DEFAULT false NOT NULL,
	"about_kind" text,
	"about_id" uuid,
	"summary" text DEFAULT '' NOT NULL,
	"internal" boolean DEFAULT false NOT NULL,
	"flagged_at" timestamp with time zone,
	"flagged_by" uuid,
	"flag_note" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "play_log_flow_check" CHECK ("play_log"."flow" in ('new', 'grow', 'issues', 'builds', 'enh', 'questions')),
	CONSTRAINT "play_log_level_check" CHECK ("play_log"."level" in ('off', 'draft', 'send')),
	CONSTRAINT "play_log_outcome_check" CHECK ("play_log"."outcome" in ('drafted', 'sent', 'done', 'skipped', 'refused')),
	CONSTRAINT "play_log_about_kind_check" CHECK ("play_log"."about_kind" is null or "play_log"."about_kind" in ('issue', 'client_ask', 'enhancement', 'build', 'deal', 'question', 'run', 'client')),
	CONSTRAINT "play_log_about_check" CHECK (("play_log"."about_kind" is null) = ("play_log"."about_id" is null)),
	CONSTRAINT "play_log_summary_check" CHECK (char_length("play_log"."summary") <= 300)
);
